<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { createProjectApi, pathId, newKey } from '../api.js';
import { useResource } from '../hooks.js';
import HistoryDeletionControls from '../history/HistoryDeletionControls.vue';
import { useHistoryDeletion, reportDeletionLabel } from '../history/useHistoryDeletion.js';
import { Button, ErrorBox, Loading, Empty, PageHeader } from '../ui/index.js';
import { dateTime, STATUS } from '../domain.js';
import TargetsFields from './TargetsFields.vue';
import TrendChart from './TrendChart.vue';
import ReportOverview from './ReportOverview.vue';
import MonitoringCards from './MonitoringCards.vue';
import NodeExecutionDetails from './NodeExecutionDetails.vue';
import ReportAnalytics from './ReportAnalytics.vue';
import { buildTargets, metric, verdictLabels, reportStatuses, targetFields } from './targets.js';
const props=defineProps({runId:{type:String,default:''},readOnly:Boolean,projectName:String});
const emit=defineEmits(['clear-run']);
const api=createProjectApi();
const timelineDetailsOpen=ref(false),timelinePage=ref(0);
const timelineRows=computed(()=>report.data?.timeline?.slice(timelinePage.value*100,(timelinePage.value+1)*100)||[]);
const search=ref(''), query=ref(''), status=ref(''), verdict=ref(''), offset=ref(0), selected=ref(''), run=ref(props.runId), tab=ref('overview'), issueOffset=ref(0), sort=ref('latency'), busy=ref(false), error=ref(null), revisionOpen=ref(false), targets=ref({}), compareIDs=ref([]), comparison=ref(null);
const list=useResource(()=>`/pressure-reports?${new URLSearchParams({search:query.value,status:status.value,verdict:verdict.value,limit:'20',offset:String(offset.value)})}`,10000);
const deletion=useHistoryDeletion({path:'/pressure-reports',kind:'报告',items:()=>list.data?.items||[],readOnly:()=>props.readOnly,onDeleted:()=>{selected.value='';run.value='';emit('clear-run');comparison.value=null;compareIDs.value=[];offset.value=0;list.refresh();}});
const latest=useResource(()=>run.value&&!selected.value?`/runs/${pathId(run.value)}/pressure-report`:null,5000);
watch(()=>latest.data,id=>{if(id?.id)selected.value=id.id;});
watch(()=>latest.error,problem=>{if(problem?.status===404&&problem.code!=='pressure_report_missing'){run.value='';selected.value='';emit('clear-run');}});
watch(()=>props.runId,id=>{run.value=id;selected.value='';comparison.value=null;});
const report=useResource(()=>selected.value?`/pressure-reports/${pathId(selected.value)}`:null,5000,{stop:data=>['READY','FAILED'].includes(data?.status)});
const doc=computed(()=>report.data);
const downloadedSources=ref(new Set()), exporting=ref(false);
const issues=useResource(()=>doc.value?.status==='READY'&&tab.value==='issues'?`/pressure-reports/${pathId(selected.value)}/issues?limit=20&offset=${issueOffset.value}&sort=${sort.value}`:null);
watch(selected,()=>{timelineDetailsOpen.value=false;timelinePage.value=0;downloadedSources.value=new Set();tab.value='overview';issueOffset.value=0;revisionOpen.value=false;targets.value={};});
watch([status,verdict,query],()=>offset.value=0);watch(sort,()=>{issueOffset.value=0;});
defineExpose({hasUnsavedChanges:()=>revisionOpen.value&&Object.values(targets.value).some(value=>value!==''),isBusy:()=>deletion.state.busy||busy.value||exporting.value,saveChanges:async()=>{throw new Error('请先生成或取消测后评审，再切换项目');}});
let request=null, compareController, compareGeneration=0, generateController, generateGeneration=0;
const comparing=ref(false);
function cancelCompare(){compareGeneration++;compareController?.abort();compareController=null;comparing.value=false;}
watch([selected,run,compareIDs],cancelCompare,{flush:'sync'});
onBeforeUnmount(cancelCompare);
function cancelGenerate(){generateGeneration++;generateController?.abort();generateController=null;busy.value=false;}
watch([selected,run],cancelGenerate,{flush:'sync'});
watch(()=>props.readOnly,value=>{if(value){cancelGenerate();revisionOpen.value=false;}});
onBeforeUnmount(cancelGenerate);
async function generate(rebuild=false, revision=false, extra={}){
 if(busy.value||props.readOnly)return;error.value=null;
 const generation=++generateGeneration,controller=new AbortController();generateController=controller;
 try{
 const reportTargets=revision?buildTargets(targets.value):undefined;
 if(revision&&!reportTargets)throw new Error('请至少填写一项测后验收目标');
 const id=doc.value?.run_id||run.value;if(!id)throw new Error('请先选择任务');
 const body={...(rebuild?{rebuild:true}:{}),...(reportTargets?{report_targets:reportTargets}:{}),...(extra?.analysis_options?{analysis_options:extra.analysis_options}:{})};
 const snapshot=JSON.stringify({id,body});if(request?.snapshot!==snapshot)request={snapshot,key:newKey()};busy.value=true;
 const result=await api(`/runs/${pathId(id)}/pressure-report`,{method:'POST',body,idempotencyKey:request.key,signal:controller.signal});
 if(generation!==generateGeneration)return;
 request=null;generateController=null;selected.value=result.id;report.refresh();list.refresh();revisionOpen.value=false;
 }catch(problem){if(generation===generateGeneration&&problem.name!=='AbortError')error.value=problem;}finally{if(generation===generateGeneration){generateController=null;busy.value=false;}}
}
async function exportHTML(){
 if(exporting.value||!selected.value)return;exporting.value=true;error.value=null;
 const id=selected.value;
 try{const blob=await api(`/pressure-reports/${pathId(id)}/export.html`,{blob:true});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='pressure-report.html';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}catch(problem){error.value=problem;}finally{exporting.value=false;}
}
async function compare(){
 cancelCompare();const generation=compareGeneration,ids=[...compareIDs.value],controller=new AbortController();compareController=controller;comparing.value=true;error.value=null;
 try{const result=await api(`/pressure-reports/compare?${new URLSearchParams({left:ids[0],right:ids[1]})}`,{signal:controller.signal});if(generation===compareGeneration&&!selected.value&&!run.value)comparison.value=result;}
 catch(problem){if(generation===compareGeneration&&problem.name!=='AbortError')error.value=problem;}
 finally{if(generation===compareGeneration){compareController=null;comparing.value=false;}}
}
function toggleCompare(id){compareIDs.value=compareIDs.value.includes(id)?compareIDs.value.filter(value=>value!==id):[...compareIDs.value.slice(-1),id];}
async function download(source){try{const url=source.download_url;if(!url||!url.startsWith('/api/')||url.startsWith('//'))throw new Error('此来源暂无可用下载地址');const blob=await api(url.slice(4),{blob:true});downloadedSources.value=new Set([...downloadedSources.value,source.id]);const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=source.name||'原始文件';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}catch(problem){error.value=problem;}}
const qualityLabels={COMPLETE:'完整',PARTIAL:'部分缺失',MISSING:'缺失',UNKNOWN:'未知',EMPTY:'空文件',READY:'可用',FAILED:'读取失败',VALID:'已校验',VERIFIED:'已校验',PARSE_PARTIAL:'部分可解析'};
const unitLabel=unit=>({ms:' 毫秒',s:' 秒',seconds:' 秒',rps:' 次/秒','req/s':' 次/秒','requests/s':' 次/秒','%':'%'}[unit]||unit||'');
const metricDefinitions=[['success_rate','请求成功率','%'],['rps','每秒请求数',' 次/秒'],['p95_ms','95% 请求耗时',' 毫秒'],['duration_seconds','持续时间',' 秒']];
const metrics=computed(()=>metricDefinitions.map(([key,label,unit])=>[key,doc.value?.metrics?.sample_scope==='ordinary_samples'?label:({success_rate:'采样记录成功率',rps:'每秒采样记录数',p95_ms:'95% 采样记录耗时'}[key] || label),unit]));
const names=Object.fromEntries([...targetFields.map(([key,label])=>[key,label]),...metricDefinitions.map(([key,label])=>[key,label]),['sample_count','样本数'],['failure_count','失败数'],['p99_ms','99% 请求耗时（毫秒）'],['plan_sha256','脚本校验值'],['environment_id','执行环境'],['cluster_id','执行集群'],['timeout_seconds','任务超时（秒）'],['environment_revision','环境版本'],['load','负载配置'],['analysis_options','分析设置'],['targets','验收目标'],['sample_scope','统计口径'],['metric_status','指标完整度'],['node_coverage','节点覆盖'],['environment','执行环境'],['workers','执行节点'],['plan','脚本版本'],['cluster','执行集群']]);
const issueCategories={sample_failure:'采样失败',request_failure:'请求失败',runtime:'执行端运行日志'};
const issueLevels={ERROR:'错误',WARN:'警告',WARNING:'警告',FATAL:'严重错误',INFO:'信息'};
const issueTime=timestamp=>Number.isFinite(timestamp)?new Date(timestamp).toLocaleString('zh-CN',{hour12:false}):'未记录';
function value(value){const labels={ordinary_samples:'普通请求样本',sample_records:'采样记录（分类未确认）',COMPLETE:'完整',PARTIAL:'部分缺失',UNKNOWN:'未知'};if(typeof value==='string'&&Object.hasOwn(labels,value))return labels[value];return value===null||value===undefined?'缺少数据':typeof value==='object'?JSON.stringify(value):String(value);}

</script>
<template>
<div class="pressure-reports">
<PageHeader title="压测报告" subtitle="从原始请求记录了解结果、验收目标与证据覆盖。"><Button v-if="selected || run" @click="selected='';run='';comparison=null">返回报告列表</Button></PageHeader>
<ErrorBox :error="error"/>
<template v-if="comparison"><section class="surface report-card"><h2>报告对比</h2><Button @click="comparison=null">关闭对比</Button><p>{{ comparison.left?.run_name }} · 版本 {{ comparison.left?.version }} ↔ {{ comparison.right?.run_name }} · 版本 {{ comparison.right?.version }}</p><div v-for="(warning,i) in comparison.warnings" :key="i" class="notice warning">{{ typeof warning==='string'?warning:warning.message }}<p v-if="warning.key">{{ names[warning.key] || '条件' }}：{{ value(warning.left) }} → {{ value(warning.right) }}</p></div><div class="table-scroll"><table><thead><tr><th>指标或条件</th><th>左侧</th><th>右侧</th><th>变化量</th></tr></thead><tbody><tr v-for="(difference,i) in comparison.differences" :key="i"><td>{{ names[difference.key] || difference.key }}</td><td>{{ value(difference.left) }}</td><td>{{ value(difference.right) }}</td><td>{{ value(difference.delta) }}</td></tr></tbody></table></div><p>不同环境、脚本或节点条件下的数字不能直接作为性能提升结论。</p></section></template>
<template v-else-if="!selected && !run">
<section class="surface report-card"><form class="report-actions" @submit.prevent="query=search.trim()"><input v-model="search" aria-label="搜索报告" placeholder="搜索任务名称或 ID"/><select v-model="status" aria-label="报告状态"><option value="">全部状态</option><option v-for="(label,key) in reportStatuses" :key="key" :value="key">{{ label }}</option></select><select v-model="verdict" aria-label="验收结论"><option value="">全部结论</option><option v-for="(label,key) in verdictLabels" :key="key" :value="key">{{ label }}</option></select><Button type="submit">搜索</Button><Button :disabled="compareIDs.length!==2" @click="compare">对比所选两份报告</Button><Button v-if="comparing" @click="cancelCompare">取消对比</Button></form><ErrorBox :error="list.error" :retry="list.refresh"/><Loading v-if="list.loading&&!list.data"/><HistoryDeletionControls :model="deletion" kind="报告" :read-only="readOnly" :project-name="projectName"/><div class="table-scroll"><table><thead><tr><th class="history-select"><input type="checkbox" aria-label="全选本页报告" :checked="deletion.allSelected.value" :indeterminate="deletion.partial.value" :disabled="readOnly || deletion.state.busy || !deletion.available.value.length" @change="deletion.togglePage($event.target.checked)"/></th><th>对比</th><th>任务 / 版本</th><th>环境</th><th>状态</th><th>结论</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in list.data?.items" :key="item.id"><td class="history-select"><input type="checkbox" :aria-label="`选择报告 ${reportDeletionLabel(item)}`" :checked="deletion.state.selected.includes(item.id)" :disabled="readOnly || deletion.state.busy" @change="deletion.toggle(item.id,$event.target.checked)"/></td><td><input type="checkbox" :aria-label="`对比 ${item.run_name} 版本 ${item.version}`" :checked="compareIDs.includes(item.id)" @change="toggleCompare(item.id)"/></td><td><button class="report-link" @click="selected=item.id">{{ item.run_name || item.run_id }} · 版本 {{ item.version }}</button></td><td>{{ item.environment_name || '未记录' }}</td><td>{{ reportStatuses[item.status] || '未知状态' }}</td><td>{{ verdictLabels[item.verdict_status] || '等待评审' }}</td><td>{{ dateTime(item.created_at) }}</td><td><Button variant="danger-outline" :aria-label="`删除报告 ${reportDeletionLabel(item)}`" :disabled="readOnly || deletion.state.busy" @click="deletion.open('single',item)">删除</Button></td></tr></tbody></table></div><Empty v-if="list.data&&!list.data.items?.length" title="暂无匹配报告">可从任务详情生成历史任务报告，或调整搜索条件。</Empty><div class="report-actions report-pagination"><span>共 {{ list.data?.total ?? 0 }} 份</span><Button :disabled="offset===0" @click="offset-=20">上一页</Button><Button :disabled="offset+20>=(list.data?.total??0)" @click="offset+=20">下一页</Button></div></section>
</template>
<template v-else>
<ErrorBox v-if="latest.error?.code!=='pressure_report_missing'" :error="latest.error" :retry="latest.refresh"/><ErrorBox :error="report.error" :retry="report.refresh"/><Loading v-if="(latest.loading||report.loading)&&!doc"/>
<section v-if="latest.error?.code==='pressure_report_missing'" class="surface report-card"><h2>此任务尚无压测报告</h2><p>生成后将按原始记录评审，缺失数据会明确披露。</p><Button :disabled="busy || readOnly" @click="generate()">生成报告</Button></section>
<section v-if="doc" class="surface report-card"><div v-if="doc.originals_status==='NOT_CHECKED_AFTER_RESTORE'" class="notice warning" role="alert"><strong>恢复后原始文件尚未核验</strong><p>{{ doc.originals_notice || '数据库恢复不包含原始文件，请实际尝试鉴权下载以确认当前可用性。' }}</p><p>下方校验信息记录的是历史解析结果，不能证明当前原始文件仍可下载。重新解析也需要原始文件。</p></div><div class="report-actions"><div class="report-heading"><h2>{{ doc.run_name || doc.run_id }}</h2><p>{{ doc.environment_name || '环境未记录' }} · {{ doc.plan_name || '脚本未记录' }} · 版本 {{ doc.version }} · {{ dateTime(doc.created_at) }} · 任务状态：{{ STATUS[doc.run_status || doc.run?.status]?.[0] || '未记录' }}</p></div><Button v-if="doc.status==='READY'" :disabled="exporting" @click="exportHTML">{{ exporting?'正在导出…':'导出离线 HTML' }}</Button><Button :disabled="busy || readOnly" @click="generate(true)">重新解析</Button><Button :disabled="busy || readOnly" @click="revisionOpen=!revisionOpen">测后调整验收目标</Button></div>
<div v-if="revisionOpen" class="report-revision"><TargetsFields v-model="targets" :disabled="busy || readOnly"/><Button :disabled="busy || readOnly" @click="generate(false,true)">生成新评审版本</Button></div>
<div v-if="doc.status!=='READY'" class="notice warning" role="status">{{ reportStatuses[doc.status] || '状态未知' }}<p>{{ typeof doc.error==='object'?doc.error?.message:doc.error }}</p><Button v-if="doc.previous_ready_id" @click="selected=doc.previous_ready_id">查看上一份可用报告</Button></div>
<template v-else>
<div class="report-verdict" :class="doc.verdict?.status==='PASS'?'pass':'warning'" role="status"><strong>{{ verdictLabels[doc.verdict?.status] || '证据不足，无法判定' }}</strong><span>{{ doc.verdict?.explanation || '仅展示实际结果，不判定达标。' }}</span></div>
<p class="report-evidence">指标完整度：{{ qualityLabels[doc.quality?.metric_status] || '未知' }} · 日志完整度：{{ qualityLabels[doc.quality?.log_status] || '未知' }} · 节点覆盖：{{ {COMPLETE:'完整',PARTIAL:'部分缺失',UNKNOWN:'未知'}[doc.quality?.node_coverage] || '未知' }}</p>
<div class="report-metrics"><div v-for="[key,label,unit] in metrics" :key="key"><span>{{ label }}</span><strong>{{ metric(doc.metrics?.[key],unit) }}</strong></div></div>
<details class="report-disclosure"><summary>统计口径与数据质量<span v-if="doc.quality?.warnings?.length"> · {{ doc.quality.warnings.length }} 条提示</span></summary>
<p class="report-explanation">统计范围：{{ doc.metrics?.sample_scope==='ordinary_samples'?'普通请求样本（事务记录另计）':'采样记录（分类未确认，不可整体判定达标）' }}。p95 表示 95% 的请求记录耗时不超过此值，并非 95% 用户的耗时。分位算法：{{ doc.metrics?.percentile_method==='log_histogram_1pct_upper_bound'?'对数直方图上界估算（约 1% 精度）':doc.metrics?.percentile_method || '未记录' }}。</p>
<div v-for="(warning,i) in doc.quality?.warnings" :key="i" class="notice warning">{{ typeof warning==='string'?warning:warning.message }}</div></details>
<nav class="tabs" aria-label="报告内容"><button v-for="[key,label] in [['overview','总览'],['analytics','性能分析'],['nodes','接口执行详情'],['issues','失败原因'],['monitoring','中间件与 JVM'],['sources','数据来源']]" :key="key" :class="{active:tab===key}" @click="tab=key">{{ label }}</button></nav>
<ReportAnalytics v-if="tab==='analytics'" :key="selected" :report-id="selected" :busy="busy || readOnly" @reparse="generate(true,false,$event)"/>
<NodeExecutionDetails v-if="tab==='nodes'" :key="selected" title="接口执行详情" :report-id="selected" :busy="busy || readOnly" @reparse="generate(true)"/>
<template v-if="tab==='overview'"><details class="report-disclosure" :open="!!doc.verdict?.checks?.length"><summary>目标对比</summary><p class="report-explanation">{{ doc.targets_origin==='POST_RUN'?'本版本采用测后调整的验收目标；压测前冻结的目标保留在原版本。':doc.targets_origin==='TASK'?'本版本采用任务创建时冻结的验收目标。':'验收目标来源未记录，未设置的目标不判定达标。' }}</p><div class="table-scroll"><table><thead><tr><th>指标</th><th>验收目标</th><th>实际结果</th><th>判定</th></tr></thead><tbody><tr v-for="check in doc.verdict?.checks" :key="check.key"><td>{{ names[check.key] || check.label }}</td><td>{{ metric(check.target,unitLabel(check.unit)) }}</td><td>{{ metric(check.actual,unitLabel(check.unit)) }}</td><td>{{ {PASS:'达到目标',FAIL:'未达目标',INCOMPLETE:'数据不足',NOT_SET:'未设置'}[check.status] || '未设置' }}<small>{{ check.detail }}</small></td></tr><tr v-for="[key,label,unit] in !doc.verdict?.checks?.length?metrics:[]" :key="key"><td>{{ label }}</td><td>未设置</td><td>{{ metric(doc.metrics?.[key],unit) }}</td><td>未设置</td></tr></tbody></table></div></details><h3 v-if="doc.findings?.length">分析发现与建议</h3><section v-for="(finding,i) in doc.findings" :key="i" class="report-finding"><h4>{{ finding.title }} <small>{{ finding.origin==='rule'?'规则分析':'分析结论' }} · {{ issueLevels[finding.level?.toUpperCase()] || finding.level || '级别未记录' }}</small></h4><p>{{ finding.detail }}</p><p>{{ finding.recommendation }}</p><small>证据引用：{{ finding.evidence_refs?.join('、') || '未提供' }}</small></section>
<ReportAnalytics :key="`overview-analytics-${selected}`" :report-id="selected" overview :busy="busy || readOnly" @reparse="generate(true,false,$event)"><template #core-trend><h3>请求处理与响应耗时趋势</h3><TrendChart v-if="doc.timeline?.length" :timeline="doc.timeline" :rate-label="metrics[1][1]" :latency-label="metrics[2][1]"/><p v-else>缺少可用趋势数据。</p><details v-if="doc.timeline?.length" :open="timelineDetailsOpen" @toggle="timelineDetailsOpen=$event.target.open"><summary>查看每个时间桶的精确数值</summary><template v-if="timelineDetailsOpen"><div class="table-scroll"><table><thead><tr><th>时间</th><th>桶宽</th><th>记录数</th><th>失败数</th><th>{{ metrics[1][1] }}</th><th>平均耗时</th><th>95% 耗时</th></tr></thead><tbody><tr v-for="row in timelineRows" :key="row.timestamp_ms"><td>{{ dateTime(row.timestamp_ms) }}</td><td>{{ metric(row.width_ms,' 毫秒') }}</td><td>{{ metric(row.sample_count) }}</td><td>{{ metric(row.failure_count) }}</td><td>{{ metric(row.rps,' 次/秒') }}</td><td>{{ metric(row.mean_ms,' 毫秒') }}</td><td>{{ metric(row.p95_ms,' 毫秒') }}</td></tr></tbody></table></div><div class="report-actions"><span>共 {{ doc.timeline.length }} 个时间桶 · 第 {{ timelinePage+1 }} 页</span><Button aria-label="上一页时间桶" :disabled="timelinePage===0" @click="timelinePage--">上一页</Button><Button aria-label="下一页时间桶" :disabled="(timelinePage+1)*100>=doc.timeline.length" @click="timelinePage++">下一页</Button></div></template></details></template></ReportAnalytics><ReportOverview :report="doc"/></template>
<template v-if="tab==='issues'"><label>排序 <select v-model="sort" aria-label="明细排序"><option value="latency">耗时优先</option><option value="failures">失败次数优先</option></select></label><ErrorBox :error="issues.error" :retry="issues.refresh"/><div class="table-scroll"><table><thead><tr><th>问题 / 分类</th><th>次数</th><th>来源 / 行号</th><th>步骤与时间</th><th>详情</th></tr></thead><tbody><tr v-for="issue in issues.data?.items" :key="issue.id"><td>{{ issue.label }}<small>{{ issueCategories[issue.category] || issue.category || '分类未记录' }}</small><small>{{ issueLevels[issue.level?.toUpperCase()] || issue.level || '级别未记录' }}</small></td><td>{{ metric(issue.count) }}</td><td>{{ issue.source_name || (issue.source_kind==='jtl'?'JTL 请求记录':issue.source_kind==='log'?'压测端日志':'来源未记录') }} · {{ issue.line_from ?? '未知' }}–{{ issue.line_to ?? '未知' }}</td><td>{{ issue.step_label || '步骤未记录' }}<small><span>首次出现</span>：{{ issueTime(issue.first_at) }}</small><small><span>最后出现</span>：{{ issueTime(issue.last_at) }}</small></td><td class="report-issue-message">{{ issue.message || '未保存摘要' }}</td></tr></tbody></table></div><p v-if="!issues.data?.items?.length">暂无可展示记录。日志缺失或为空不能推断“无异常”。</p><div class="report-actions"><span>共 {{ issues.data?.total ?? 0 }} 条</span><Button :disabled="issueOffset===0" @click="issueOffset-=20">上一页明细</Button><Button :disabled="issueOffset+20>=(issues.data?.total??0)" @click="issueOffset+=20">下一页明细</Button></div></template>
<MonitoringCards v-if="tab==='overview'||tab==='monitoring'" :report-id="doc.id" :extensions="doc.extensions || {}" :compact="tab==='overview'" @inspect="tab='monitoring'"/>
<template v-if="tab==='sources'"><h3>证据与来源覆盖</h3><p>预期节点：{{ doc.quality?.expected_nodes?.join('、') || '未记录' }} · 已观察节点：{{ doc.quality?.observed_nodes?.join('、') || '未记录' }} · 无效行：{{ metric(doc.quality?.invalid_rows) }}</p><p class="report-explanation">节点覆盖以 JTL 实际可识别的节点为准；无效行、缺失节点或来源文件会影响结论可信度。业务成功仍需脚本中保存的业务断言证明。</p><div class="table-scroll"><table><thead><tr><th>原始文件 / 大小</th><th>历史解析状态 / 错误</th><th>历史校验信息</th><th>下载</th></tr></thead><tbody><tr v-for="source in doc.sources" :key="source.id"><td>{{ source.name }}<small>{{ metric(source.size,' B') }}</small></td><td>{{ qualityLabels[source.status] || '状态未知' }} {{ source.error }}</td><td>有效 {{ metric(source.valid_rows) }} 行 · 无效 {{ metric(source.invalid_rows) }} 行<br/>SHA256 {{ source.sha256 || '未记录' }}</td><td><p>{{ downloadedSources.has(source.id)?'本次鉴权下载成功':'当前可用性尚未确认' }}</p><Button :disabled="!source.download_url" @click="download(source)">尝试下载原始文件</Button></td></tr></tbody></table></div><p v-if="!doc.sources?.length">缺少来源文件证据。</p><p class="muted">解析器 {{ doc.parser_version || '未记录' }} · 数据结构 {{ doc.schema_version || '未记录' }}</p></template>
</template></section></template></div>
</template>
